<template>
  <div class="row items-center q-pt-sm q-pb-sm q-pr-md">
    <q-space />
    <q-btn class="q-mr-sm" flat to="/settings/supplier/layouts_builder/default_fields" color="primary" :label="$t('supplier_fields')" />
    <f-btn
      :label="$t('new')"
      icon="add"
      @click="() => layoutDialog = true"
    />
  </div>

  <div class="container">
    <div class="full-width">
      <DocBitsTable
        :rows="document_types || []"
        :columns="columns"
        :loading="loading"
        row-key="document_name"
        table-id="supplier_layouts_table"
        :features="{
          sorting: false,
          filtering: false,
          selection: false,
          bulkActions: false,
          rowActions: true,
          resizable: false,
          pagination: false,
          columnReorder: false,
          columnSettings: false,
          stickyFirstColumn: false,
          stickyLastColumn: true,
        }"
        :row-actions="rowActions"
        no-data-label="no_record_found"
        table-class="supplier-layouts-table-height"
        flat-style
        @row-action="handleRowAction"
        @row-click="handleRowClick"
      >
        <!-- Title column -->
        <template #body-cell-title="{ row }">
          {{ row.title }}
        </template>

        <!-- Document name column -->
        <template #body-cell-document_name="{ row }">
          {{ $t(row.document_name) }}
        </template>
      </DocBitsTable>
    </div>
  </div>

  <!-- Dialog starts -->
  <q-dialog v-model="layoutDialog">
    <q-card style="width: 600px; max-width: 60vw">
      <q-toolbar class="bg-primary">
        <q-toolbar-title class="text-white">
          <span> {{ $t('create_layout') }} </span>
        </q-toolbar-title>
        <q-btn flat round dense icon="close" class="text-white" @click="reset" v-close-popup />
      </q-toolbar>

      <q-card-section>
        <div class="col-sm-12 col-md-12 col-lg-12">
          <q-form @submit="createLayout" @reset="reset">
            <div class="row">
              <div class="col-sm-12 col-md-12 col-lg-12 q-pa-md">
                <q-input
                  dense
                  outlined
                  v-model="title"
                  required
                  :label="$t('title')"
                />
              </div>
              <div class="col-sm-12 col-md-12 col-lg-12 q-pa-md">
                <q-select
                  outlined
                  dense
                  v-model="doc_type_name"
                  :options="docTypeOption"
                  emit-value
                  map-options
                  required
                  :label="$t('document_name')"
                ></q-select>
              </div>
              <div class="float-right q-ml-auto q-pa-md q-mt-md">
                <f-btn
                  :label="$t('cancel')"
                  appearance="cancel"
                  v-close-popup
                  @click="reset"
                />
                <f-btn
                  :label="$t('save')"
                  class="q-ml-sm"
                  type="submit"
                />
              </div>
            </div>
          </q-form>
        </div>
      </q-card-section>
    </q-card>
  </q-dialog>
  <!-- dialog ends -->

  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref, computed } from 'vue';
import { useSupplierLayoutsStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import { supplierDocumentType } from './formBuilderConstants';
import { supplierApiService } from 'src/services';
import { DocBitsTable } from 'src/components/Table';
import Loader from 'src/components/Loader.vue';
import type {
  UnifiedTableColumn,
  RowActionItem,
  RowActionPayload,
} from 'src/components/Table';
import { useTranslate } from '@tolgee/vue';

export default defineComponent({
  name: 'SupplierLayoutsList',
  components: {
    DocBitsTable,
    Loader,
  },
  mounted() {
    this.init();
  },
  data() {
    return {
      layoutDialog: false,
      doc_type_name: '',
      title: '',
      translate_key: '',
      docTypeOption: [
        {
          label: this.$t(
            supplierDocumentType.SUPPLIER_MANAGEMENT.toUpperCase(),
          ),
          value: supplierDocumentType.SUPPLIER_MANAGEMENT,
        },
        {
          label: this.$t(supplierDocumentType.SUPPLIER_USER.toUpperCase()),
          value: supplierDocumentType.SUPPLIER_USER,
        },
      ],
    };
  },
  setup() {
    const { t } = useTranslate();
    const supplier_layouts_store = useSupplierLayoutsStore();
    const { document_types, loading } = storeToRefs(supplier_layouts_store);
    const { getSupplierType } = supplier_layouts_store;

    // Column definitions for DocBitsTable
    const columns = computed<UnifiedTableColumn[]>(() => [
      {
        name: 'title',
        label: t.value('title'),
        field: 'title',
        sortable: false,
        align: 'left',
      },
      {
        name: 'document_name',
        label: t.value('document_name'),
        field: 'document_name',
        sortable: false,
        align: 'left',
      },
    ]);

    // Row actions for edit only
    const rowActions: RowActionItem[] = [
      {
        key: 'edit',
        label: 'edit_layout',
        icon: 'edit',
        color: 'primary',
      },
    ];

    return {
      getSupplierType,
      document_types,
      loading,
      columns,
      rowActions,
      t,
    };
  },
  methods: {
    async init() {
      try {
        this.loading = true;
        await this.getSupplierType();
      } catch (err: any) {
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    handleRowAction(payload: RowActionPayload) {
      const row = payload.row;
      if (payload.action === 'edit') {
        this.goSupplierLayoutDetails(row);
      }
    },
    handleRowClick(payload: { row: any }) {
      this.goSupplierLayoutDetails(payload.row);
    },
    goSupplierLayoutDetails(row: any) {
      this.$router.push(`/settings/supplier/layouts-builder/${row.title.replace(/\s+/g, '_').toUpperCase()}`);
    },
    validation() {
      if (!this.doc_type_name) {
        notify.error(this.$t('please_select_document_type'));
        return false;
      }
      return true;
    },
    async createLayout() {
      if (!this.validation()) {
        return;
      }
      this.loading = true;
      const data = {
        doc_type_name: this.doc_type_name,
        title: this.title,
        translate_key: this.translate_key,
      };
      try {
        const response = await supplierApiService.createLayoutSupplier(data);
        await this.getSupplierType();
        if (response.success === false) {
          notify.error(response.message);
        } else {
          notify.success(this.$t('MSG_SAVE'));
        }
      } catch (error: any) {
        notify.success(error?.message);
      } finally {
        this.loading = false;
        this.layoutDialog = false;
        this.reset();
      }
    },
    reset() {
      this.doc_type_name = '';
      this.title = '';
      this.translate_key = '';
    },
  },
});
</script>

<style lang="scss" scoped>
:deep(.supplier-layouts-table-height) {
  height: calc(100vh - 120px) !important;
}
</style>
